def has_close_elements(numbers: List[float], threshold: float) -> bool:
    for i in range(len(numbers)):
        for j in range(i+1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    current_group = ""
    open_count = 0
    for char in paren_string:
        if char == "(":
            open_count += 1
            current_group += char
        elif char == ")":
            open_count -= 1
            current_group += char
            if open_count == 0:
                groups.append(current_group)
                current_group = ""
        else:
            continue
    return groups

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        raise ValueError("Input list is empty")
    mean = sum(numbers) / len(numbers)
    deviations = [abs(x - mean) for x in numbers]
    return sum(deviations) / len(numbers)

def find_topmost_carpet(n, carpets, point):
    # Initialize a dictionary to store the carpet information
    carpet_dict = {}
    for i in range(n):
        # Get the current carpet's information
        a, b, g, k = carpets[i]
        # Check if the current carpet covers the point
        if a <= point[0] < a + g and b <= point[1] < b + k:
            # If it does, add it to the dictionary with its index as the key
            carpet_dict[i] = (a, b, g, k)

    # If the dictionary is empty, return -1
    if not carpet_dict:
        return -1

    # Otherwise, find the topmost carpet by checking the y-coordinate of each carpet
    topmost_carpet = None
    for i in carpet_dict:
        if topmost_carpet is None or carpet_dict[i][1] > carpet_dict[topmost_carpet][1]:
            topmost_carpet = i

    return topmost_carpet

def max_value_on_paths(N, grid_values):
    # Initialize a 2D array to store the maximum sum of values collected on each path
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Iterate over the grid values and update the maximum sum for each path
    for x, y, value in grid_values:
        if x == 0 and y == 0:
            continue
        dp[x][y] = max(dp[x - 1][y], dp[x][y - 1]) + value

    # Return the maximum sum of values collected on the two paths
    return dp[N][N]

