def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a dictionary to store the maximum value that can be picked within the time limit
    # for each herb
    max_values = {}

    # Loop through each herb and calculate the maximum value that can be picked within the time limit
    for herb in herbs:
        time_required, value = herb
        if time_required <= T:
            max_values[herb] = value
        else:
            max_values[herb] = 0

    # Calculate the maximum total value of herbs that can be picked within the time limit
    total_value = sum(max_values.values())

    return total_value

def mod_inverse(a, b):
    # Find the gcd of a and b
    gcd, x, y = egcd(a, b)

    # Check if gcd is 1
    if gcd != 1:
        return None

    # Calculate the modular inverse
    return x % b

def egcd(a, b):
    # Find the gcd of a and b
    if a == 0:
        return (b, 0, 1)
    else:
        gcd, x, y = egcd(b % a, a)
        return (gcd, y - (b // a) * x, x)

def find_most_unhappy_day(schedule):
    # Calculate the total hours spent in school and extra classes for each day
    total_hours = [sum(day) for day in schedule]

    # Find the day with the maximum total hours above the threshold (8 hours)
    max_unhappiness = max(total_hours) - 8
    unhappy_days = [i for i, hours in enumerate(total_hours) if hours > max_unhappiness]

    # If there are multiple days with the same level of maximum unhappiness, return the earliest day
    if len(unhappy_days) > 1:
        return min(unhappy_days)
    # If Jinjin is not unhappy on any day, return 0
    elif len(unhappy_days) == 0:
        return 0
    # Otherwise, return the day with the maximum unhappiness
    else:
        return unhappy_days[0]

def jinjin_savings_plan(budgets: List[int]) -> int:
    total_savings = 0
    for i, budget in enumerate(budgets):
        if budget >= 100:
            savings = budget // 100 * 100
            total_savings += savings
        else:
            return -i
    total_savings *= 1.2
    return int(total_savings)

